/**
 * Every migration, in order, as one file to paste into the Supabase SQL
 * editor.
 *
 *   node scripts/bundle-migrations.js [outFile]
 *
 * For a project that has the CLI linked, `supabase db push` is the better
 * road — it records what has been applied. This is for the first run on a
 * fresh project, or for anyone who has the dashboard open and not the CLI.
 * It is generated, never committed, so it cannot drift from the files it
 * came from.
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const DIR = path.join(ROOT, 'supabase/migrations');
const OUT = process.argv[2] || path.join(ROOT, 'supabase/all-migrations.sql');

const files = fs.readdirSync(DIR).filter((f) => f.endsWith('.sql')).sort();
const header = `-- The One Thing — every migration, in order, generated by
-- scripts/bundle-migrations.js. Run it once, on a fresh project, in the
-- Supabase SQL editor. It is not idempotent: running it twice fails on the
-- first \`create type\`, which is the safe way round.
--
-- ${files.length} files: ${files.join(', ')}
`;

const body = files
  .map((f) => `\n\n-- ${'='.repeat(74)}\n-- ${f}\n-- ${'='.repeat(74)}\n\n${fs.readFileSync(path.join(DIR, f), 'utf8').trimEnd()}`)
  .join('\n');

fs.writeFileSync(OUT, `${header}${body}\n`);
console.log(JSON.stringify({ out: path.relative(ROOT, OUT), files, bytes: fs.statSync(OUT).size }, null, 2));
